SELECT COUNT(*)
FROM business_partner bp
WHERE bp.partner_id = #{customerId}
    AND bp.company_id = #{companyId}
    AND bp.customer_yn = 'Y'
    AND bp.use_yn = 'Y'

SELECT COUNT(*)
FROM warehouse w
WHERE w.warehouse_id = #{warehouseId}
    AND w.company_id = #{companyId}
    AND w.use_yn = 'Y'

