UPDATE sales_order
SET
    order_status = 'CONFIRMED',
    confirmed_at = SYSTIMESTAMP,
    confirmed_by = #{confirmedBy},
    updated_at = SYSTIMESTAMP,
    updated_by = #{confirmedBy}
WHERE sales_order_id = #{salesOrderId}
    AND company_id = #{companyId}
    AND order_status = 'DRAFT'
